diff --git a/cmd/entire/cli/remote_topology_test.go b/cmd/entire/cli/remote_topology_test.go
new file mode 100644
index 000000000..1df8ba0b1
--- /dev/null
+++ b/cmd/entire/cli/remote_topology_test.go
@@ -0,0 +1,159 @@
+package cli
+
+import (
+	"errors"
+	"strings"
+	"testing"
+
+	"github.com/entireio/cli/cmd/entire/cli/strategy"
+)
+
+// describeTopology renders a topology under the headings `entire doctor` really
+// passes, so these tests assert on the text a user actually sees.
+func describeTopology(t *testing.T, topo remoteTopology) string {
+	t.Helper()
+	var b strings.Builder
+	topo.describeCheckpointDestination(&b, doctorCheckpointNoteHeaders)
+	return b.String()
+}
+
+// TestCheckpointNote_FailedElectionReplacesTheDestinationClaim is the reported
+// bug (see remoteTopology.electionErr). Asserts the false claims are gone, not
+// merely that the new text is present.
+func TestCheckpointNote_FailedElectionReplacesTheDestinationClaim(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{
+		destinations: []remoteDestination{
+			{name: "origin", pushURLs: []string{"https://example.com/a.git"}},
+			{name: "publish", pushURLs: []string{"https://example.com/b.git"}},
+		},
+		electionErr: &strategy.CheckpointPushRemoteNotConfiguredError{Remote: "gone"},
+	}
+
+	out := describeTopology(t, topo)
+
+	for _, want := range []string{
+		"Checkpoint sync: DISABLED",
+		`checkpoint_push_remote names "gone"`,
+		"origin, publish",
+		"no session history",
+		"settings.local.json",
+	} {
+		if !strings.Contains(out, want) {
+			t.Errorf("disabled note should contain %q, got:\n%s", want, out)
+		}
+	}
+	for _, absent := range []string{
+		"single elected remote",
+		"entire status",
+		"Checkpoint destination: REVIEW",
+	} {
+		if strings.Contains(out, absent) {
+			t.Errorf("disabled note must not claim %q, got:\n%s", absent, out)
+		}
+	}
+}
+
+// TestCheckpointNote_FailedElectionReportsASingleRemoteRepo covers the other
+// half of the same bug: the note only ever spoke up about ambiguity, so a
+// one-remote repo whose sync was switched off by the same typo got no report
+// at all.
+func TestCheckpointNote_FailedElectionReportsASingleRemoteRepo(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{
+		destinations: []remoteDestination{{name: "origin", pushURLs: []string{"https://example.com/a.git"}}},
+		electionErr:  &strategy.CheckpointPushRemoteNotConfiguredError{Remote: "gone"},
+	}
+	if topo.ambiguous() {
+		t.Fatal("setup: a single-remote repo must not be ambiguous, or this asserts nothing")
+	}
+
+	out := describeTopology(t, topo)
+	if !strings.Contains(out, "Checkpoint sync: DISABLED") {
+		t.Errorf("an unambiguous repo whose sync is off should still be reported, got:\n%s", out)
+	}
+	if !strings.Contains(out, "Affected remotes: origin") {
+		t.Errorf("the report should name the remote that now carries nothing, got:\n%s", out)
+	}
+}
+
+// TestCheckpointNote_UnrecognizedElectionErrorGetsNoRemedy pins the matched-cause
+// rule documented on CheckpointPushRemoteNotConfiguredError: an unreadable
+// settings file is fail-closed too, and "name a real remote" is not its fix.
+func TestCheckpointNote_UnrecognizedElectionErrorGetsNoRemedy(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{
+		destinations: []remoteDestination{{name: "origin", pushURLs: []string{"https://example.com/a.git"}}},
+		electionErr:  errors.New("cannot read settings to resolve the checkpoint sync remote: boom"),
+	}
+
+	out := describeTopology(t, topo)
+	if !strings.Contains(out, "cannot read settings") {
+		t.Errorf("the unmatched error should still be reported, got:\n%s", out)
+	}
+	if strings.Contains(out, "Fix:") {
+		t.Errorf("an unmatched error must get no remedy, got:\n%s", out)
+	}
+}
+
+// TestCheckpointNote_PinnedRemoteKeepsSyncingThroughAFailedElection guards the
+// exemption the pre-push gate applies before consulting the election: a
+// dedicated checkpoint_remote URL is addressed directly, not elected, so its
+// checkpoints still ship and the user must not be told sync is off.
+func TestCheckpointNote_PinnedRemoteKeepsSyncingThroughAFailedElection(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{
+		destinations: []remoteDestination{
+			{name: "origin", pushURLs: []string{"https://example.com/a.git"}, pinned: true},
+		},
+		electionErr: &strategy.CheckpointPushRemoteNotConfiguredError{Remote: "gone"},
+	}
+
+	if out := describeTopology(t, topo); out != "" {
+		t.Errorf("a repo whose every remote is pinned still syncs; got:\n%s", out)
+	}
+}
+
+// TestCheckpointNote_FailedElectionWithNoRemotes covers syncDisabled's other
+// disjunct: a repo with no remotes syncs nowhere regardless, but the broken
+// setting travels with the settings file to clones that do have remotes, so it
+// is still reported — without an affected-remotes list it cannot populate.
+func TestCheckpointNote_FailedElectionWithNoRemotes(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{electionErr: &strategy.CheckpointPushRemoteNotConfiguredError{Remote: "gone"}}
+
+	out := describeTopology(t, topo)
+	if !strings.Contains(out, "Checkpoint sync: DISABLED") || !strings.Contains(out, "Fix:") {
+		t.Errorf("a remoteless repo should still get the report and its remedy, got:\n%s", out)
+	}
+	if strings.Contains(out, "Affected remotes") {
+		t.Errorf("there are no remotes to affect, got:\n%s", out)
+	}
+}
+
+// TestCheckpointNote_SuccessfulElectionKeepsTheAmbiguityNote checks the fix did
+// not cost the note its original job.
+func TestCheckpointNote_SuccessfulElectionKeepsTheAmbiguityNote(t *testing.T) {
+	t.Parallel()
+
+	topo := remoteTopology{
+		destinations: []remoteDestination{
+			{name: "origin", pushURLs: []string{"https://example.com/a.git"}},
+			{name: "publish", pushURLs: []string{"https://example.com/b.git"}},
+		},
+	}
+
+	out := describeTopology(t, topo)
+	if !strings.Contains(out, "Checkpoint destination: REVIEW") ||
+		!strings.Contains(out, "single elected remote") {
+		t.Errorf("an elected repo with several remotes should still get the note, got:\n%s", out)
+	}
+	if strings.Contains(out, "DISABLED") {
+		t.Errorf("nothing is disabled here, got:\n%s", out)
+	}
+}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// Checkpoint destinations are unambiguous in the ordinary single-remote,
// single-URL repo and stop being unambiguous in two topologies users set up
// deliberately. Neither is broken, but in both the destination is decided by
// something other than "the repo I work in", so it is worth saying out loud once
// at `entire enable` and on demand from `entire doctor` rather than letting
// someone discover it when a resume comes up empty.

// remoteDestination is one remote and what checkpoints pushed to it would do.
type remoteDestination struct {
	name string
	// pushURLs are the URLs a push to this remote delivers to, in git's order.
	pushURLs []string
	// pinned reports that remote.PushURL resolves this remote to a configured
	// checkpoint_remote, so its own push URLs are irrelevant to checkpoints.
	//
	// Asked of the resolver rather than derived from settings on purpose: a
	// checkpoint_remote that is *present* is not necessarily *in effect* —
	// PushURL falls back to the push remote on an owner mismatch, an
	// unparseable URL, or a protocol it cannot map. Reading settings directly
	// would report "pinned" while pushes really went elsewhere, the same class
	// of bug the CoreOrigin() rule in CLAUDE.md exists to prevent.
	pinned bool
}

// fansOut reports whether checkpoints pushed to this remote face more than one
// destination.
func (d remoteDestination) fansOut() bool { return !d.pinned && len(d.pushURLs) > 1 }

// remoteTopology summarizes checkpoint-destination ambiguity in this repo.
type remoteTopology struct {
	// destinations is every configured remote, sorted by name.
	destinations []remoteDestination
	// primaryIsRefs reports whether the git-refs backend is active, which
	// decides what a fanning-out remote means for checkpoints.
	primaryIsRefs bool
	// electionErr is the fail-closed outcome of the checkpoint sync election,
	// nil when a remote was elected (or when there is simply nothing to elect).
	//
	// Asked of the resolver for the same reason `pinned` is: every sentence
	// this type writes about where checkpoints go is a claim about what the
	// election decided, and a note that narrates the election without consulting
	// it states its rules as facts. It did — it told a repo whose election had
	// failed closed that checkpoints "sync to a single elected remote" and to run
	// `entire status` to see which one, when the answer was none and nothing was
	// syncing anywhere.
	electionErr error
}

// inspectRemoteTopology reads the repo's remotes and checkpoint configuration.
// Best-effort and offline: every failure yields an empty topology, which reports
// nothing, because this is advisory output that must never obstruct enable or
// doctor.
func inspectRemoteTopology(ctx context.Context) remoteTopology {
	var t remoteTopology

	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return t
	}

	// One `git remote -v` rather than `git remote` plus a get-url per remote:
	// it already applies git's pushurl-replaces-url rule and lists every push
	// URL in order, so N+1 subprocesses collapse to one — and all of it runs in
	// repoRoot instead of mixing dir-aware and cwd-dependent lookups.
	pushURLs, err := pushURLsByRemote(ctx, repoRoot)
	if err != nil {
		logging.Debug(ctx, "remote topology: could not read remotes", slog.String("error", err.Error()))
		return t
	}

	names := make([]string, 0, len(pushURLs))
	for name := range pushURLs {
		names = append(names, name)
	}
	sort.Strings(names)

	for _, name := range names {
		dest := remoteDestination{name: name, pushURLs: pushURLs[name]}
		if _, enabled, err := remote.PushURL(ctx, name); err == nil {
			dest.pinned = enabled
		}
		t.destinations = append(t.destinations, dest)
	}

	if cpCfg, err := settings.LoadCheckpointsConfig(ctx); err == nil {
		t.primaryIsRefs = checkpoint.PrimaryIsRefs(cpCfg)
	}

	// Local-only, like everything else here: the resolver reads settings and
	// .git/config, both memoized by the root context's git-remote cache, and
	// never dials.
	_, t.electionErr = strategy.ResolveCheckpointSyncRemote(ctx)

	return t
}

// pushURLsByRemote parses `git remote -v` into remote name -> push URLs in git's
// own order.
func pushURLsByRemote(ctx context.Context, dir string) (map[string][]string, error) {
	out, err := gitRunner(ctx, dir, "remote", "-v")
	if err != nil {
		return nil, fmt.Errorf("list git remotes: %w", err)
	}
	urls := make(map[string][]string)
	for _, line := range strings.Split(out, "\n") {
		// "<name>\t<url> (push)" — fetch lines are the same shape and ignored.
		name, rest, found := strings.Cut(strings.TrimSpace(line), "\t")
		if !found || !strings.HasSuffix(rest, "(push)") {
			continue
		}
		url := strings.TrimSpace(strings.TrimSuffix(rest, "(push)"))
		if url != "" {
			urls[name] = append(urls[name], url)
		}
	}
	// An empty map is a legitimate answer (a repo with no remotes), so it is
	// returned as such rather than as an error the caller would have to classify.
	return urls, nil
}

// ambiguous reports whether anything is worth telling the user: a remote whose
// checkpoints face several push URLs, or several remotes to choose between.
func (t remoteTopology) ambiguous() bool {
	unpinned := 0
	for _, d := range t.destinations {
		if d.fansOut() {
			return true
		}
		if !d.pinned {
			unpinned++
		}
	}
	return unpinned > 1
}

// syncDisabled reports that the election failed closed AND that the failure
// costs this repo something: at least one remote whose pushes would otherwise
// have carried checkpoints now carries none.
//
// A pinned remote is exempt because the pre-push gate exempts it — a dedicated
// checkpoint_remote URL is addressed directly rather than elected, so its
// checkpoints still ship (the gate applies the election only when
// ps.hasCheckpointURL() is false). A repo whose every remote is pinned is
// therefore syncing normally and is told nothing. A repo with no remotes at all
// is still told: nothing syncs there either way, but the broken setting is real
// and travels with the settings file to clones that do have remotes.
func (t remoteTopology) syncDisabled() bool {
	if t.electionErr == nil {
		return false
	}
	return len(t.destinations) == 0 || len(t.unpinnedNames()) > 0
}

// describeSyncDisabled writes the fail-closed election: what is broken, what it
// costs, and — only for the cause we recognize — how to fix it.
//
// The remedy is gated on errors.As rather than printed unconditionally, because
// the resolver also fails closed on an unreadable settings file; advice about
// naming a real remote would be the wrong answer to a file we could not open.
func (t remoteTopology) describeSyncDisabled(w io.Writer, header string) {
	fmt.Fprintln(w, header)

	var misconfigured *strategy.CheckpointPushRemoteNotConfiguredError
	if errors.As(t.electionErr, &misconfigured) {
		fmt.Fprintf(w, "  checkpoint_push_remote names %q, which is not one of this repo's remotes,\n",
			misconfigured.Remote)
		fmt.Fprintln(w, "  so nothing is elected to carry checkpoints.")
	} else {
		fmt.Fprintf(w, "  %s.\n", t.electionErr)
	}

	// The remote list gets a line of its own rather than a slot inside a
	// sentence: every line here is hand-wrapped, and a name list interpolated
	// mid-sentence moves the wrap by however long the names happen to be.
	if names := t.unpinnedNames(); len(names) > 0 {
		fmt.Fprintf(w, "  Affected remotes: %s\n", strings.Join(names, ", "))
		fmt.Fprintln(w, "  Pushes to them carry your code but no session history, which stays in")
		fmt.Fprintln(w, "  this clone.")
	}

	if misconfigured == nil {
		return
	}
	fmt.Fprintln(w, "  Fix: remove strategy_options.checkpoint_push_remote to let Entire elect one,")
	fmt.Fprintln(w, "  or point it at a remote this repo actually has.")
	fmt.Fprintln(w, "  A remote name is a per-clone fact: prefer .entire/settings.local.json, since a")
	fmt.Fprintln(w, "  committed one disables checkpoint sync in every clone that lacks that name.")
}

// describeCheckpointDestination writes an explanation of where checkpoints go,
// under the header matching what it found. Writes nothing when the destination
// is unambiguous and the election succeeded.
//
// The two conditions are exclusive on purpose: while sync is disabled there is
// no destination to describe, so the ambiguity paragraphs below — which all
// narrate where checkpoints land — would be describing traffic that is not
// flowing. They become true again once the setting is fixed, which is what the
// remedy asks for.
func (t remoteTopology) describeCheckpointDestination(w io.Writer, headers checkpointNoteHeaders) {
	if t.syncDisabled() {
		t.describeSyncDisabled(w, headers.disabled)
		return
	}
	if !t.ambiguous() {
		return
	}

	fmt.Fprintln(w, headers.ambiguous)

	for _, d := range t.destinations {
		if !d.fansOut() {
			continue
		}
		fmt.Fprintf(w, "  Remote %q pushes to %d URLs:\n", d.name, len(d.pushURLs))
		for i, u := range d.pushURLs {
			marker := "  "
			if i == 0 && t.primaryIsRefs {
				marker = "→ "
			}
			fmt.Fprintf(w, "    %s%s\n", marker, gitremote.RedactURLOrPath(u))
		}
		if t.primaryIsRefs {
			fmt.Fprintln(w, "    Checkpoints go to the first URL only; the others receive your code but")
			fmt.Fprintln(w, "    no session history. Clone that first repository to resume elsewhere.")
		} else {
			fmt.Fprintln(w, "    Checkpoints are pushed to every URL. If one rejects them or is")
			fmt.Fprintln(w, "    unreachable it is reported and left behind, and only the fetch URL is")
			fmt.Fprintln(w, "    ever reconciled — so those URLs can fall permanently out of date.")
		}
	}

	if names := t.unpinnedNames(); len(names) > 1 {
		fmt.Fprintf(w, "  This repo has %d remotes (%s).\n", len(names), strings.Join(names, ", "))
		fmt.Fprintln(w, "    Checkpoints sync to a single elected remote — not to whichever one you")
		fmt.Fprintln(w, "    push to. A push to any other remote carries your code but no session")
		fmt.Fprintln(w, "    history. Run `entire status` to see the elected destination and how many")
		fmt.Fprintln(w, "    checkpoints are waiting for it.")
	}

	fmt.Fprintln(w, "  To pin one repository for checkpoints, set checkpoint_remote in")
	fmt.Fprintln(w, "  .entire/settings.json (or .entire/settings.local.json to keep it to this clone).")
}

// unpinnedNames lists the remotes whose checkpoint destination is not already
// pinned by a checkpoint_remote.
func (t remoteTopology) unpinnedNames() []string {
	var names []string
	for _, d := range t.destinations {
		if !d.pinned {
			names = append(names, d.name)
		}
	}
	return names
}

// checkpointNoteHeaders are the caller's headings for the two conditions this
// note reports. Separate strings because they are separate verdicts: a disabled
// sync is a misconfiguration to fix, while an ambiguous destination is a working
// repo whose owner should know which remote gets the history.
type checkpointNoteHeaders struct {
	disabled  string
	ambiguous string
}

// doctorCheckpointNoteHeaders phrases the note as one of doctor's verdicts,
// matching the "<subject>: <STATE>" shape its other checks print.
//
// A var rather than a literal at the call site so the tests assert on the text
// a user actually sees: a copy in the test file stays green when the heading
// here changes, which is the one thing those tests exist to catch.
var doctorCheckpointNoteHeaders = checkpointNoteHeaders{
	disabled:  "Checkpoint sync: DISABLED",
	ambiguous: "Checkpoint destination: REVIEW",
}

// printCheckpointDestinationNote explains where checkpoints go when this repo's
// remotes make that a choice, and says so when they go nowhere. Shared by
// `entire enable` — the moment a user is most likely to be looking, and the
// least surprising place to learn it — and by `entire doctor`, which reports it
// on demand. Silent on the ordinary repo, so it adds nothing to the common
// output.
func printCheckpointDestinationNote(ctx context.Context, w io.Writer, headers checkpointNoteHeaders) {
	inspectRemoteTopology(ctx).describeCheckpointDestination(w, headers)
}

package strategy

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os/exec"
	"slices"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

// CheckpointSyncRemoteSource identifies which precedence rule elected the
// checkpoint sync remote.
type CheckpointSyncRemoteSource string

const (
	// SyncRemoteSourceConfig: strategy_options.checkpoint_push_remote.
	SyncRemoteSourceConfig CheckpointSyncRemoteSource = "config"
	// SyncRemoteSourceObserved: elected by evidence — a past push that agreed
	// with the branch's declared push destination (see
	// commitCapturedSyncRemote). Named for what was observed, not for the
	// latch that recorded it, which is why the internal names still say "capture".
	SyncRemoteSourceObserved CheckpointSyncRemoteSource = "observed"
	// SyncRemoteSourceDefault: "origin" exists.
	SyncRemoteSourceDefault CheckpointSyncRemoteSource = "default"
	// SyncRemoteSourceSole: exactly one remote configured.
	SyncRemoteSourceSole CheckpointSyncRemoteSource = "sole"
	// SyncRemoteSourceFirst: first remote in .git/config order.
	SyncRemoteSourceFirst CheckpointSyncRemoteSource = "first"
)

// CheckpointSyncRemote is the single git remote elected to carry checkpoint
// data. Name is empty when no remotes are configured.
type CheckpointSyncRemote struct {
	Name   string
	Source CheckpointSyncRemoteSource
}

// CheckpointPushRemoteNotConfiguredError is one of the two ways election fails
// closed: strategy_options.checkpoint_push_remote names a remote this repo does
// not have, so nothing is elected and no push carries checkpoint data until the
// setting is fixed. The other way is an unreadable settings file, which stays an
// opaque wrapped error.
//
// A distinct type (match it with errors.As) because the two want different
// remedies, and a caller that cannot tell them apart must offer neither — the
// same rule the .entire directory errors follow. The message is what
// `entire status` prints verbatim, so it states the consequence as well as the
// cause.
type CheckpointPushRemoteNotConfiguredError struct {
	// Remote is the name the setting gave, kept so a caller can name it
	// without re-reading settings.
	Remote string
}

func (e *CheckpointPushRemoteNotConfiguredError) Error() string {
	return fmt.Sprintf(
		"checkpoint_push_remote %q is not a configured git remote; checkpoint sync disabled until fixed",
		e.Remote)
}

// ResolveCheckpointSyncRemote elects the one configured git remote that
// checkpoint data syncs to. Pure local lookup — no network. Precedence:
// checkpoint_push_remote setting (fail-closed if the named remote does not
// exist), then the captured election (evidence-elected by a past push that
// agreed with the branch's declared push destination; fail-soft if that
// remote is gone), then "origin", then the sole remote, then the first remote
// in .git/config order. It knows nothing about the checkpoint_remote URL
// feature; callers exempt that case themselves.
//
// Deliberately NOT keyed on the branch's tracking config alone
// (branch.<name>.pushRemote / remote.pushDefault / branch.<name>.remote).
// Election is compared against the remote of the push actually being made, so
// electing the tracking remote from config at rest silently drops checkpoint
// sync on every push to any OTHER remote — `git push <other> HEAD`, a
// `git clone -o base` whose checkpoints go to a separately added origin, any
// repo with remote.pushDefault set.
// TestAlternates_RelativeObjectAlternate_CheckpointSync is the regression:
// it clones with `-o base` and pushes checkpoints to `origin`, and a tracking
// tier makes the pre-push hook a silent no-op. The captured tier is the safe
// form of the same intent: tracking config nominates a remote, but only an
// actual push that delivers checkpoints to it elects it (see
// commitCapturedSyncRemote).
//
// The fork setup that motivated the tracking tier — clone the base repo, add
// your fork, push there, with origin unpushable — is served automatically by
// capture, or explicitly by checkpoint_push_remote. Either way the result is
// readable from the same clone: the read paths (resume, explain, discovery)
// consult the elected remote first and fall back to origin as a read-only
// legacy tier (see CheckpointReadRemotes). Tracking config on its own still
// elects nothing, for the silent-no-op reason above.
func ResolveCheckpointSyncRemote(ctx context.Context) (CheckpointSyncRemote, error) {
	// Fail closed on an unreadable settings file: election must never
	// override a checkpoint_push_remote the file may contain but we could
	// not read, or checkpoints would silently re-route away from the remote
	// the user configured for isolation.
	s, err := settings.Load(ctx)
	if err != nil {
		return CheckpointSyncRemote{}, fmt.Errorf("cannot read settings to resolve the checkpoint sync remote: %w", err)
	}
	if name := s.GetCheckpointPushRemote(); name != "" {
		if !isConfiguredRemote(ctx, name) {
			return CheckpointSyncRemote{}, &CheckpointPushRemoteNotConfiguredError{Remote: name}
		}
		return CheckpointSyncRemote{Name: name, Source: SyncRemoteSourceConfig}, nil
	}

	// Captured tier: fail-soft, unlike the explicit setting above — capture
	// is automatic state, so a captured remote that was since renamed or
	// removed falls through to the default tiers instead of disabling sync.
	for _, name := range loadCapturedSyncRemotes(ctx) {
		if isConfiguredRemote(ctx, name) {
			return CheckpointSyncRemote{Name: name, Source: SyncRemoteSourceObserved}, nil
		}
		logging.Debug(ctx, "captured checkpoint sync remote is not configured; falling through",
			slog.String("remote", name))
	}

	remotes := configuredRemotesInConfigOrder(ctx)
	switch {
	case len(remotes) == 0:
		return CheckpointSyncRemote{}, nil
	case slices.Contains(remotes, "origin"):
		return CheckpointSyncRemote{Name: "origin", Source: SyncRemoteSourceDefault}, nil
	case len(remotes) == 1:
		return CheckpointSyncRemote{Name: remotes[0], Source: SyncRemoteSourceSole}, nil
